import{_ as t,c as a,o as n,ag as o}from"./chunks/framework.B-XtCDNB.js";const p=JSON.parse('{"title":"Payments","description":"","frontmatter":{"subtitle":"Configure payment methods and track payment status."},"headers":[],"relativePath":"merchant/order/payments.md","filePath":"merchant/order/payments.md"}'),i={name:"merchant/order/payments.md"};function s(r,e,l,d,h,m){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h1><p>Payment processing in Meloncart is handled by the <strong><a href="https://octobercms.com/plugin/responsiv-pay" target="_blank" rel="noreferrer">Responsiv.Pay</a></strong> plugin. This plugin provides the payment gateway infrastructure, invoice management, and payment method configuration. Meloncart integrates with it to connect orders to payments seamlessly.</p><h2 id="payment-methods" tabindex="-1">Payment Methods <a class="header-anchor" href="#payment-methods" aria-label="Permalink to &quot;Payment Methods&quot;">​</a></h2><p>Payment methods are configured under <strong>Settings → Payment Methods</strong> (provided by the Responsiv.Pay plugin). Each payment method represents a way customers can pay for their orders: such as credit card via Stripe, PayPal, bank transfer, or cash on delivery.</p><h3 id="setting-up-a-payment-method" tabindex="-1">Setting Up a Payment Method <a class="header-anchor" href="#setting-up-a-payment-method" aria-label="Permalink to &quot;Setting Up a Payment Method&quot;">​</a></h3><p>Click <strong>New Payment Method</strong> to add one. Each payment method has:</p><ul><li><strong>Name</strong>: The display name shown to customers at checkout (e.g., &quot;Credit Card&quot;, &quot;PayPal&quot;).</li><li><strong>Driver</strong>: The payment gateway driver that handles the transaction (e.g., Stripe, PayPal, RazorPay, offline).</li><li><strong>Enabled</strong>: Whether the method is available to customers.</li><li><strong>Configuration</strong>: Driver-specific settings such as API keys, webhook URLs, and mode (test/live).</li></ul><h3 id="order-specific-settings" tabindex="-1">Order-Specific Settings <a class="header-anchor" href="#order-specific-settings" aria-label="Permalink to &quot;Order-Specific Settings&quot;">​</a></h3><p>Meloncart extends payment method drivers with additional settings:</p><h4 id="for-offline-payment-methods" tabindex="-1">For Offline Payment Methods <a class="header-anchor" href="#for-offline-payment-methods" aria-label="Permalink to &quot;For Offline Payment Methods&quot;">​</a></h4><p>Payment methods without an online payment form (such as bank transfer, cash on delivery, or invoice payment) have these additional settings:</p><ul><li><strong>Order Start Status</strong>: The order status to assign when a customer selects this payment method at checkout. This allows you to route orders differently based on how the customer pays. For example, bank transfer orders might start in a &quot;Awaiting Payment&quot; status.</li><li><strong>Suppress Order Notifications</strong>: When enabled, the standard &quot;new order&quot; notification email is not sent for orders using this payment method. This is useful when you want to handle notification for certain payment types manually.</li></ul><h4 id="for-online-payment-methods" tabindex="-1">For Online Payment Methods <a class="header-anchor" href="#for-online-payment-methods" aria-label="Permalink to &quot;For Online Payment Methods&quot;">​</a></h4><p>Payment methods with an online payment form (such as Stripe or PayPal) have:</p><ul><li><strong>Order Status</strong>: The status to assign to the order upon successful payment. This defaults to &quot;Paid&quot; but can be changed to match your workflow.</li></ul><h2 id="payment-processing-flow" tabindex="-1">Payment Processing Flow <a class="header-anchor" href="#payment-processing-flow" aria-label="Permalink to &quot;Payment Processing Flow&quot;">​</a></h2><h3 id="standard-flow" tabindex="-1">Standard Flow <a class="header-anchor" href="#standard-flow" aria-label="Permalink to &quot;Standard Flow&quot;">​</a></h3><ol><li><strong>Customer selects payment method</strong>: During checkout, the customer chooses from available payment methods.</li><li><strong>Order is created</strong>: When the customer places the order, Meloncart creates an order record and an associated invoice in the Responsiv.Pay system.</li><li><strong>Payment is processed</strong>: For online payment methods, the customer is redirected to a payment page (or a payment form is displayed inline). For offline methods, the order is created immediately with the configured start status.</li><li><strong>Payment confirmation</strong>: When the payment gateway confirms the transaction, the invoice is marked as paid.</li><li><strong>Order status updates</strong>: Meloncart detects the paid invoice and automatically: <ul><li>Marks the order as payment processed (recording the timestamp).</li><li>Transitions the order to the &quot;Paid&quot; status (or the configured status for that payment method).</li><li>Sends status notification emails if configured.</li><li>Decreases stock levels for all items in the order.</li></ul></li></ol><h3 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h3><p>Each order has an associated invoice managed by Responsiv.Pay. The invoice mirrors the order&#39;s items, totals, and payment information. When you edit an order in the backend (adding or removing items, changing the shipping method, etc.), the invoice is automatically synchronized to reflect the current order state.</p><p>Invoices track:</p><ul><li><strong>Items</strong>: Each order item is linked to a corresponding invoice item.</li><li><strong>Total</strong>: The total amount due.</li><li><strong>Payment Method</strong>: The selected payment gateway.</li><li><strong>Payment Status</strong>: Whether the invoice has been paid.</li><li><strong>Payment Log</strong>: A record of all payment attempts and transactions.</li></ul><h3 id="invoice-templates" tabindex="-1">Invoice Templates <a class="header-anchor" href="#invoice-templates" aria-label="Permalink to &quot;Invoice Templates&quot;">​</a></h3><p>Invoice templates control the layout and content of invoices for printing and PDF generation. Navigate to <strong>Settings → Invoice Templates</strong> (provided by the Responsiv.Pay plugin) to manage your templates. A default template is created during installation.</p><p>Each template has:</p><ul><li><strong>Name</strong>: A descriptive name for the template.</li><li><strong>Code</strong>: A unique identifier.</li><li><strong>Is Default</strong>: Whether this is the default template used for new invoices.</li></ul><p>Templates use the same syntax field system as <a href="./shipping-labels.html">shipping labels</a> and <a href="./packing-slips.html">packing slips</a>. The <strong>HTML</strong> and <strong>CSS</strong> tabs contain the template markup and styles. Syntax fields embedded in the HTML (such as <code>{text name=&quot;company_name&quot;}</code>) are extracted on save and appear as editable form fields in the <strong>Invoice</strong> tab.</p><p>The default template includes:</p><ul><li><strong>Company logo</strong>: Uploaded via a file upload syntax field.</li><li><strong>Company name and address</strong>: Editable text fields for your business details.</li><li><strong>Company registration number</strong>: For displaying ABN, VAT, or other registration numbers.</li><li><strong>Customer details</strong>: Populated from the invoice&#39;s billing address.</li><li><strong>Invoice items table</strong>: Description, quantity, unit price, and total for each line item.</li><li><strong>Totals</strong>: Subtotal, tax, and total amount due.</li></ul><h4 id="printing-an-invoice" tabindex="-1">Printing an Invoice <a class="header-anchor" href="#printing-an-invoice" aria-label="Permalink to &quot;Printing an Invoice&quot;">​</a></h4><p>From an order&#39;s preview page, click <strong>View Invoice</strong> to navigate to the invoice preview. The invoice preview page displays the rendered invoice and includes a <strong>Print Invoice</strong> button that opens your browser&#39;s print dialog.</p><h4 id="emailing-an-invoice" tabindex="-1">Emailing an Invoice <a class="header-anchor" href="#emailing-an-invoice" aria-label="Permalink to &quot;Emailing an Invoice&quot;">​</a></h4><p>From the invoice preview page, click <strong>Email Invoice</strong> to open the email form. The form lets you:</p><ul><li><strong>To</strong>: The recipient email address, pre-filled from the invoice&#39;s email or the linked user account.</li><li><strong>Subject</strong>: The email subject line, defaults to &quot;Invoice {number}&quot;.</li><li><strong>Message</strong>: A customizable message body, pre-filled from the <code>pay:invoice</code> mail template.</li><li><strong>Attach PDF</strong>: Attach the invoice as a PDF file (enabled by default).</li><li><strong>Send myself a copy</strong>: BCC the email to the logged-in admin user.</li></ul><p>The invoice&#39;s <strong>Sent At</strong> timestamp is updated each time an email is sent.</p><h4 id="automatic-emailing" tabindex="-1">Automatic Emailing <a class="header-anchor" href="#automatic-emailing" aria-label="Permalink to &quot;Automatic Emailing&quot;">​</a></h4><p>To automatically email invoices when payment is received, enable <strong>Email Invoice on Payment</strong> under <strong>Settings → Payment Settings → Invoices</strong>. When enabled, the invoice is emailed to the customer with a PDF attachment immediately after the payment gateway confirms the transaction.</p><h4 id="selecting-a-template" tabindex="-1">Selecting a Template <a class="header-anchor" href="#selecting-a-template" aria-label="Permalink to &quot;Selecting a Template&quot;">​</a></h4><p>Each invoice has a template dropdown where you can select which template to use. If left as &quot;Use Default&quot;, the template marked as default will be used. You can create multiple templates for different purposes (e.g., a formal template for business clients and a simpler one for retail customers).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Templates that are in use by one or more invoices cannot be deleted. Remove or reassign the template from all invoices before deleting it.</p></div><h2 id="payment-status" tabindex="-1">Payment Status <a class="header-anchor" href="#payment-status" aria-label="Permalink to &quot;Payment Status&quot;">​</a></h2><p>An order&#39;s payment status is determined by whether the <code>payment_processed_at</code> timestamp has been set:</p><ul><li><strong>Unpaid</strong>: The order has no payment processed timestamp. The customer may not have completed payment, or the payment gateway has not yet confirmed the transaction.</li><li><strong>Paid</strong>: The order has a payment processed timestamp, indicating successful payment.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The payment status is set automatically when the payment gateway confirms the transaction. You generally do not need to manage this manually. However, for offline payment methods (bank transfer, etc.), transitioning the order to the &quot;Paid&quot; status in the backend will mark the payment as processed.</p></div><h3 id="pending-payments" tabindex="-1">Pending Payments <a class="header-anchor" href="#pending-payments" aria-label="Permalink to &quot;Pending Payments&quot;">​</a></h3><p>Some payment gateways (such as PayPal) may not confirm a transaction immediately. When this occurs, the invoice status is set to <strong>Approved</strong>, indicating the customer has submitted their payment but final confirmation is still pending.</p><p>While an invoice is in the Approved state:</p><ul><li>The payment page displays a &quot;Your payment is being processed&quot; message instead of showing payment methods, preventing the customer from paying twice.</li><li>When the customer revisits the payment page, the system automatically polls the payment gateway to check if the payment has since been confirmed. If it has, the invoice is marked as paid immediately.</li><li>If the gateway supports webhooks, the payment will also be confirmed asynchronously when the gateway sends a completion notification.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If a payment remains in the Approved state for an extended period, you can check the payment log on the associated invoice for details about the gateway&#39;s response. The payment gateway&#39;s dashboard (e.g., PayPal or Stripe) will have the definitive status of the transaction.</p></div><h2 id="store-credit" tabindex="-1">Store Credit <a class="header-anchor" href="#store-credit" aria-label="Permalink to &quot;Store Credit&quot;">​</a></h2><p>Store credit allows customers to apply a balance toward their order total at checkout. When a customer has available credit, they can apply it during checkout to reduce the amount charged to the payment gateway, or cover the full order if the balance is sufficient.</p><p>Store credit must be enabled in the Responsiv.Pay plugin settings. See <a href="./store-credit.html">Store Credit</a> for full details on enabling, issuing, and managing store credit.</p><h2 id="payment-log" tabindex="-1">Payment Log <a class="header-anchor" href="#payment-log" aria-label="Permalink to &quot;Payment Log&quot;">​</a></h2><p>Each order&#39;s payment history can be viewed through the associated invoice. The payment log records all interactions with the payment gateway, including successful charges, failed attempts, and refund transactions. This is useful for troubleshooting payment issues.</p><h2 id="multiple-payment-methods" tabindex="-1">Multiple Payment Methods <a class="header-anchor" href="#multiple-payment-methods" aria-label="Permalink to &quot;Multiple Payment Methods&quot;">​</a></h2><p>Your store can have multiple active payment methods simultaneously. At checkout, customers see all enabled payment methods that are applicable to their order. The Responsiv.Pay plugin handles the routing to the correct gateway based on the customer&#39;s selection.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For stores that sell both physical and digital products, you can set up different payment methods with different configurations. All enabled methods appear at checkout regardless of what is in the cart.</p></div>',57)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
